insert into public.products(name_bn,name_en,unit,category_id,sort_order)
select p.name_bn,p.name_en,p.unit,c.id,p.sort_order from p join c on c.name_bn=p.cat
where not exists(select 1 from public.products x where x.name_bn=p.name_bn);
